/* One portable envelope; existing validated preview flows perform each restore. */
(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const MAX=100*1024*1024;let imported=null,readTicket=0;
 const canonical=x=>JSON.stringify(x&&typeof x==='object'?(Array.isArray(x)?x.map(v=>JSON.parse(canonical(v))):Object.fromEntries(Object.keys(x).sort().map(k=>[k,JSON.parse(canonical(x[k]))]))):x);
 function checkLearning(raw){if(raw.version!==2||new Blob([JSON.stringify(raw)]).size>5000000)throw Error('Learning backup must be version 2 and under 5 MB.');const clean=window.REILearningStore.validate(raw);for(const key of ['notes','completed','drafts','quiz','checks','learningLab','learningPath','noteDraft','editDraft','resume'])if(key in raw&&canonical(raw[key])!==canonical(clean[key]))throw Error('Learning records contain invalid or unsupported values. Nothing was imported.');return clean}
 function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
 function validate(raw){
  if(raw?.kind!=='rei-workspace'||raw.version!==1||!Array.isArray(raw.projects)||raw.projects.length>5)throw Error('Choose a REI workspace backup. Older individual backups can still be opened in their original workspace.');
  if(!raw.learning||!Array.isArray(raw.learning.notes)||!Array.isArray(raw.learning.completed))throw Error('The learning notebook is missing or invalid.');
  checkLearning(raw.learning);
  for(const project of raw.projects){const checked=window.REIResearch.validate(structuredClone(project));window.REIWorkbench.stageAttachments(checked)}
  return raw;
 }
 function view(){return `<div class="container section recovery-center"><h1>Keep a copy of your work.</h1><p>One workspace backup includes your learning workbook, notebook, lesson drafts, practice, research projects and saved PDFs. No account is needed.</p><div class="actions"><button class="button primary" data-recovery-export>Download workspace backup</button><a class="text-link" href="#research">Return to research</a></div><p role="status" id="recovery-export-status">Reading your saved work…</p><h2>What your backup includes</h2><div id="recovery-inventory"></div><p>Unsubmitted research forms are not included. Session-retained proposal and reading-note edits are included where available. Save each form first. A download request cannot confirm that your browser kept the file; open the downloaded backup here to check it.</p><h2>Check or restore a workspace backup</h2><label class="button secondary">Choose workspace backup<input type="file" id="recovery-file" accept=".json,application/json"></label><p id="recovery-import-status" role="status">Checking a file does not replace or import anything.</p><div id="recovery-preview"></div><details><summary>Already have an older backup?</summary><p>Project JSON and complete PDF backups still restore through <a href="#research">Research Studio → Import a backup</a>. Learning JSON still restores through <a href="#notebook">My workspace → Import</a>. Markdown and CSV are readable exports and cannot restore a workspace.</p></details><details><summary>Recover on another device</summary><ol><li>Save your forms and download the workspace backup.</li><li>Keep the file somewhere you trust. It contains your notes and any saved PDFs.</li><li>Open REI in the other browser and choose the backup here.</li><li>Restore each project as a separate copy. Restore the learning notebook only after backing up the destination notebook.</li><li>Check the proposal, evidence links and PDFs before removing any older copy.</li></ol><p>Browser storage belongs to a browser profile. Clearing site data or private browsing can remove local work. Keep a separate backup.</p></details></div>`}
 async function inventory(){
  const host=document.querySelector('#recovery-inventory');if(!host)return;
  try{const projects=await window.REIResearch.listSaved(),learning=window.REILearningStore.snapshot();if(!host.isConnected)return;
   host.innerHTML=`<p><strong>Learning notebook:</strong> ${learning.notes.length} notes, ${Object.keys(learning.drafts).length} lesson drafts, plus your guided workbook, practice and progress.</p><ul>${projects.map(p=>`<li>${esc(p.title)} — ${p.papers.length} sources, ${p.evidence.length} evidence notes, proposal and saved PDFs.</li>`).join('')||'<li>No research projects on this device.</li>'}</ul>`;
   let record;try{record=JSON.parse(localStorage.getItem('rei-workspace-export')||'null')}catch{}
   document.querySelector('#recovery-export-status').textContent=record?'Last workspace download requested '+new Date(record.date).toLocaleString()+'. Changes since then may need a new backup.':'No workspace backup download has been recorded on this device.';
  }catch{host.textContent='Research storage could not be read. Retry after enabling browser storage. A complete workspace export cannot proceed.';document.querySelector('[data-recovery-export]').disabled=true}
 }
 async function exportAll(button){
  if(button.disabled)return;button.disabled=true;const status=document.querySelector('#recovery-export-status');status.textContent='Preparing projects and PDFs. Keep this page open…';
  try{const projects=[];let bytes=0;for(const p of await window.REIResearch.listSaved()){const backup=await window.REIWorkbench.backup(p,true,true);bytes+=new Blob([JSON.stringify(backup)]).size;if(bytes>MAX)throw Error('The workspace exceeds 100 MB. Export complete projects individually from Review & history.');projects.push(backup)}
   const bundle={kind:'rei-workspace',version:1,exported:new Date().toISOString(),learning:window.REILearningStore.snapshot(),projects};if(new Blob([JSON.stringify(bundle,null,2)]).size>MAX)throw Error('The workspace exceeds 100 MB. Export complete projects individually.');
   validate(bundle);download('rei-workspace-backup.json',bundle);try{localStorage.setItem('rei-workspace-export',JSON.stringify({date:bundle.exported}))}catch{}
   status.textContent='Workspace download requested: learning notebook and '+projects.length+' complete projects. Check that the file downloaded, then choose it below to verify its contents.';
  }catch(error){status.textContent='Backup not created. '+(error.message||'Retry when storage is available. Your work remains on this device.')}finally{button.disabled=false}
 }
 async function openRestore(index){
  if(!imported)return;validate(imported);const payload=index==='learning'?imported.learning:imported.projects[Number(index)];if(!payload)return;
  history.pushState(null,'',index==='learning'?'#notebook':'#research');await route();
  if(index==='learning')document.querySelector('[data-action="import"]').click();
  const input=document.querySelector(index==='learning'?'#backup-file':'#research-restore');if(!input){toast('Open the backup center again and retry.');return}
  const transfer=new DataTransfer();transfer.items.add(new File([JSON.stringify(payload)],'rei-restored-part.json',{type:'application/json'}));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));
 }
 document.addEventListener('click',event=>{const exportButton=event.target.closest('[data-recovery-export]');if(exportButton)exportAll(exportButton);const restore=event.target.closest('[data-recovery-restore]');if(restore&&imported)openRestore(restore.dataset.recoveryRestore).catch(()=>toast('Could not open restore preview. Keep the backup file and retry.'))});
 document.addEventListener('change',async event=>{if(event.target.id!=='recovery-file')return;const file=event.target.files[0];event.target.value='';if(!file)return;const ticket=++readTicket,status=document.querySelector('#recovery-import-status'),preview=document.querySelector('#recovery-preview');imported=null;preview.replaceChildren();status.textContent='Checking file…';try{if(file.size>MAX)throw Error('Choose a backup under 100 MB.');const raw=validate(JSON.parse(await file.text()));if(!preview.isConnected||ticket!==readTicket)return;imported=raw;status.textContent='Backup structure and attachment data checked. Nothing has been imported. Verify restored PDF rendering after import.';preview.innerHTML=`<p>Contains ${raw.learning.notes.length} learning notes and ${raw.projects.length} projects. Restore one part at a time; each opens the existing confirmation preview.</p><button class="button secondary" data-recovery-restore="learning">Preview learning notebook replacement</button><p>Learning restore replaces the destination notebook. Download its backup first. Research projects are restored as separate copies, up to the five-project limit.</p>${raw.projects.map((x,i)=>`<article><h3>${esc(x.project.title)}</h3><p>${x.project.papers.length} sources · ${x.project.evidence.length} evidence notes · ${x.project.workbench?.attachments?.length||0} PDFs</p><button class="button secondary" data-recovery-restore="${i}">Preview project restore</button></article>`).join('')}` }catch(error){if(ticket!==readTicket||!status.isConnected)return;status.textContent='Nothing imported. '+(error instanceof SyntaxError?'This is not valid JSON.':error.message||'The backup could not be read.')}});
 addEventListener('rrh:route',()=>{if(location.hash==='#backup'){inventory();if(imported){document.querySelector('#recovery-import-status').textContent='Choose your workspace file again to preview another part. The original file is unchanged.'}}});
 window.REIRecovery={view,validate,checkLearning};
})();
